import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"密钥泄漏与修复：一次 API Key 安全治理实录","description":"","frontmatter":{"title":"密钥泄漏与修复：一次 API Key 安全治理实录","date":"2026-09-29T00:00:00.000Z","tags":["安全","工程实践",".env"]},"headers":[],"relativePath":"posts/secret-hardening.md","filePath":"posts/secret-hardening.md","lastUpdated":1790688655000}'),n={name:"posts/secret-hardening.md"};function p(l,s,o,h,r,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="密钥泄漏与修复-一次-api-key-安全治理实录" tabindex="-1">密钥泄漏与修复：一次 API Key 安全治理实录 <a class="header-anchor" href="#密钥泄漏与修复-一次-api-key-安全治理实录" aria-label="Permalink to &quot;密钥泄漏与修复：一次 API Key 安全治理实录&quot;">​</a></h1><p>给帧间做安全排查时，发现 <code>pipeline.py</code> 里硬编码着一个真实的智谱 GLM API Key。这类问题在个人项目里极其常见，处理它值得完整记录一次。</p><h2 id="问题-密钥写死在代码里" tabindex="-1">问题：密钥写死在代码里 <a class="header-anchor" href="#问题-密钥写死在代码里" aria-label="Permalink to &quot;问题：密钥写死在代码里&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 错误示范</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GLM_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;d2bf********……真实 key 明文在代码里&quot;</span></span></code></pre></div><p>风险不只是&quot;不美观&quot;：代码会被 commit、push、分享，每多一个副本，密钥就多一个泄露面。</p><h2 id="排查-先确认泄漏范围" tabindex="-1">排查：先确认泄漏范围 <a class="header-anchor" href="#排查-先确认泄漏范围" aria-label="Permalink to &quot;排查：先确认泄漏范围&quot;">​</a></h2><p>动手改之前，先回答一个问题：<strong>这个 key 已经泄到哪了？</strong></p><ol><li><strong>git 历史</strong>：<code>git log --all -S &quot;key前缀&quot;</code> 扫描——结果：128 个 commit 零命中，key 从未被提交过</li><li><strong>远程仓库</strong>：检查 GitHub 远程（当时 PRIVATE）代码与数据文件——pipeline.py 无 key，data/ 只跟踪了 .gitkeep</li><li><strong>编译缓存</strong>：<code>grep -r</code> 扫 .pyc——无残留</li><li><strong>全项目文本</strong>：只剩 .env 与数据库（数据库存 provider key 是产品功能，不算泄漏）</li></ol><p>结论：泄漏面 = 仅本地工作区文件，从未外流。</p><h2 id="修复-三层改动" tabindex="-1">修复：三层改动 <a class="header-anchor" href="#修复-三层改动" aria-label="Permalink to &quot;修复：三层改动&quot;">​</a></h2><p><strong>1. 代码去硬编码。</strong> 统一从配置读：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># app/core/config.py</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GLM_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.getenv(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GLM_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pipeline.py —— 删掉硬编码，import 配置</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.core.config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> GLM_API_KEY</span></span></code></pre></div><p><strong>2. 密钥进 .env（已被 gitignore 排除）。</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># backend/.env（本文件已被 .gitignore 排除，勿提交）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GLM_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">xxxx</span></span></code></pre></div><p><strong>3. 数据目录整体忽略。</strong> 数据库和备份 jsonl 里存着 provider key，加规则防止未来误提交：</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 数据目录整体（仅保留 .gitkeep 占位）</span></span>
<span class="line"><span>backend/data/*</span></span>
<span class="line"><span>!backend/data/.gitkeep</span></span></code></pre></div><h2 id="验证-改完必须证明改对了" tabindex="-1">验证：改完必须证明改对了 <a class="header-anchor" href="#验证-改完必须证明改对了" aria-label="Permalink to &quot;验证：改完必须证明改对了&quot;">​</a></h2><ul><li><code>python -m py_compile</code> 编译通过</li><li>项目虚拟环境导入：key 从 .env 加载成功、pipeline 读取一致、代码无残留</li><li><code>git check-ignore</code> 逐个验证 frames.db / 备份 / 运行时配置全部被忽略</li><li>转公开前复查：远程无 key、data/ 未跟踪——转公开安全</li></ul><h2 id="原则" tabindex="-1">原则 <a class="header-anchor" href="#原则" aria-label="Permalink to &quot;原则&quot;">​</a></h2><ul><li><strong>密钥永远不进 git</strong>：环境变量 + .env（gitignore 排除），代码里只有占位</li><li><strong>改之前先查泄漏范围</strong>：git log -S 是第一步，别凭感觉</li><li><strong>验证用可复现命令</strong>：check-ignore、加载断言，而不是&quot;我检查过了&quot;</li></ul><blockquote><p>面试可展开：GitHub 的 secret scanning 会扫已 push 的 key，但 git 历史里的 key 要自己用 <code>git log -S</code> 找——先查范围再决定要不要重置密钥。</p></blockquote>`,22)])])}const k=i(n,[["render",p]]);export{g as __pageData,k as default};
